-- V11 — Member management (RF-003, D28).
--
-- password_change_required: a temporary password, generated by the
-- administrator, that has to be changed on first access; while it stands, the
-- API serves only /auth/me, /auth/logout and /auth/password.
--
-- credentials_changed_at: the instant of the last password change or reset. A
-- session authenticated before it is ended on its next request (D21), which
-- is what makes a password change drop sessions open in other browsers.
ALTER TABLE app_user ADD COLUMN password_change_required boolean NOT NULL DEFAULT false;
ALTER TABLE app_user ADD COLUMN credentials_changed_at timestamptz;
